(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   地质图件要素智能提取 · 示范页脚本\n   ---------------------------------------------------------\n   用合成的「扫描地质图件」演示三条智能化主线：\n     实验 1 · 目标检测：定位图例符号 / 断层线 / 钻孔柱状图\n     实验 2 · OCR 识别：把图面注记从像素读成文本\n     实验 3 · 版面分析 + 矢量追踪：理清区块、线条成矢量\n\n   文件内部分层：\n     1) Model（纯模型层，Node 可 require，供 flow.js 复用）\n     2) 浏览器接线（$ 工具 + 三屏渲染 + Bridge 桥接 + 抽屉上报）\n   ========================================================= */\n(function (root, factory) {\n  if (typeof module === 'object' && module.exports) module.exports = factory();\n  else root.Model = factory();\n})(typeof window !== 'undefined' ? window : this, function () {\n  'use strict';\n\n  var METRIC = {};\n  var M = { METRIC: METRIC };\n\n  /* ---------- 固定种子随机数（mulberry32） ---------- */\n  function mulberry32(seed) {\n    var a = seed >>> 0;\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      var t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n  M.mulberry32 = mulberry32;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n\n  /* =========================================================\n     合成扫描地质图件\n     ---------------------------------------------------------\n     W×H 栅格，背景米黄色（纸感）+ 三类对象：\n       - 断层线  ：细长曲线像素（低对比，扫描常见噪声）\n       - 图例符号：小方块 / 三角 / 圆（岩性符号，带年代风格）\n       - 注记文本：一组「字符槽」，OCR 要读的内容\n     返回栅格 + 对象清单（真值，供检测对比）。\n     ========================================================= */\n  var ROCK_SYM = [\n    { name: '砂岩', fill: '#e0c88a', mark: '↗' },\n    { name: '灰岩', fill: '#cbbf9a', mark: '△' },\n    { name: '泥岩', fill: '#b8c4b5', mark: '○' },\n    { name: '页岩', fill: '#c9c4b0', mark: '□' },\n    { name: '花岗岩', fill: '#d8b6a2', mark: '◇' }\n  ];\n  M.ROCK_SYM = ROCK_SYM;\n\n  var FAULT_COLORS = ['#8a4f27', '#7a6a4b', '#6b5a3a'];\n  var META_NAMES = ['J2', 'K1', 'T3', 'P2', 'O1', 'C1', 'D3', 'S2'];\n\n  function genScanMap(seed, W, H) {\n    W = W || 64; H = H || 48;\n    var rng = mulberry32(seed || 20261105);\n    var px = new Uint8Array(W * H);           /* 0=纸面 1=断层线 2=符号 3=注记 */\n    var conf = new Float32Array(W * H);       /* 像素置信度（符号浓淡 / 线强度） */\n\n    /* 背景纸面微噪 */\n    for (var i = 0; i < W * H; i++) { px[i] = 0; conf[i] = 0.1; }\n\n    var faults = [];\n    var nFault = 3 + Math.floor(rng() * 2);\n    for (var f = 0; f < nFault; f++) {\n      var col = FAULT_COLORS[f % FAULT_COLORS.length];\n      var y0 = 6 + rng() * (H - 16), x0 = 4 + rng() * (W - 16);\n      var amp = 1 + rng() * 3, len = 14 + rng() * 20;\n      var pts = [];\n      for (var t = 0; t <= len; t += 0.5) {\n        var x = Math.round(x0 + t);\n        var y = Math.round(y0 + amp * Math.sin(t * 0.7 + f));\n        if (x < 0 || x >= W || y < 0 || y >= H) continue;\n        px[y * W + x] = 1; conf[y * W + x] = 0.55 + rng() * 0.3;\n        pts.push([x, y]);\n      }\n      faults.push({ id: 'F' + (f + 1), color: col, pts: pts, name: '断层' + (f + 1) });\n    }\n\n    /* 图例符号：小目标，分散放 */\n    var symbols = [];\n    var nSym = 12 + Math.floor(rng() * 8);\n    for (var s = 0; s < nSym; s++) {\n      var rock = ROCK_SYM[Math.floor(rng() * ROCK_SYM.length)];\n      var sw = 5 + Math.floor(rng() * 2);   /* 符号尺寸小（检测难点） */\n      var sx = Math.floor(3 + rng() * (W - sw - 8));\n      var sy = Math.floor(3 + rng() * (H - sw - 8));\n      /* 画符号方块 */\n      for (var dy = 0; dy < sw; dy++) for (var dx = 0; dx < sw; dx++) {\n        var xi = sx + dx, yi = sy + dy;\n        if (xi < W && yi < H) { px[yi * W + xi] = 2; conf[yi * W + xi] = 0.5 + rng() * 0.4; }\n      }\n      symbols.push({ id: 'S' + (s + 1), rock: rock.name, x: sx, y: sy, w: sw, h: sw, fill: rock.fill });\n    }\n\n    /* 注记文本：字符槽（OCR 读取对象） */\n    var notes = [];\n    var nNote = 6 + Math.floor(rng() * 4);\n    for (var n = 0; n < nNote; n++) {\n      var nm = META_NAMES[Math.floor(rng() * META_NAMES.length)];\n      var cx = Math.floor(6 + rng() * (W - 14));\n      var cy = Math.floor(5 + rng() * (H - 8));\n      var cw = 2 + nm.length;   /* 字符槽宽度 */\n      for (var di = 0; di < cw; di++) {\n        var xj = cx + di, yj = cy;\n        if (xj < W && yj < H) { px[yj * W + xj] = 3; conf[yj * W + xj] = 0.6; }\n      }\n      notes.push({ id: 'N' + (n + 1), text: nm, x: cx, y: cy, w: cw, h: 1 });\n    }\n\n    return { W: W, H: H, px: px, conf: conf, faults: faults, symbols: symbols, notes: notes };\n  }\n  M.genScanMap = genScanMap;\n\n  /* =========================================================\n     目标检测（模拟 Faster R-CNN / YOLO）\n     ---------------------------------------------------------\n     用「真值对象 + 检测置信度 + 可能的漏检/误检」合成检测结果：\n       confTh 越高越保守（漏检多、误检少），越低越激进。\n     返回 { dets:[{x,y,w,h,cls,conf,hit}], recall, precision }\n     ========================================================= */\n  function detectObjects(scan, confTh, seed) {\n    var rng = mulberry32((seed || 42) + Math.round(confTh * 1000));\n    var dets = [];\n    var tp = 0, fp = 0;\n\n    function emit(x, y, w, h, cls, conf, hit) {\n      dets.push({ x: x, y: y, w: w, h: h, cls: cls, conf: conf, hit: hit });\n    }\n\n    /* 断层线检测：沿线生成若干检测框 */\n    var shouldTotal = 0;\n    for (var f = 0; f < scan.faults.length; f++) {\n      var fl = scan.faults[f];\n      /* 把断层线聚成 1—2 个检测框 */\n      var nB = 1 + (fl.pts.length > 30 ? 1 : 0);\n      shouldTotal += nB;\n      for (var b = 0; b < nB; b++) {\n        var seg = fl.pts.slice(Math.floor(b * fl.pts.length / nB), Math.floor((b + 1) * fl.pts.length / nB));\n        var minX = 1e9, minY = 1e9, maxX = -1, maxY = -1;\n        for (var q = 0; q < seg.length; q++) {\n          if (seg[q][0] < minX) minX = seg[q][0];\n          if (seg[q][0] > maxX) maxX = seg[q][0];\n          if (seg[q][1] < minY) minY = seg[q][1];\n          if (seg[q][1] > maxY) maxY = seg[q][1];\n        }\n        var cF = clamp(0.62 + rng() * 0.3 - (confTh - 0.5) * 0.6, 0.2, 0.98);\n        if (cF >= confTh) { emit(minX, minY, maxX - minX + 1, maxY - minY + 1, '断层', cF, true); tp++; }\n      }\n    }\n\n    /* 图例符号检测：小目标，confTh 高时易漏 */\n    shouldTotal += scan.symbols.length;\n    for (var s = 0; s < scan.symbols.length; s++) {\n      var sy = scan.symbols[s];\n      var cS = clamp(0.5 + rng() * 0.4 - (confTh - 0.5) * 0.9, 0.1, 0.97);\n      if (cS >= confTh) { emit(sy.x, sy.y, sy.w, sy.h, '符号', cS, true); tp++; }\n    }\n\n    /* 钻孔柱状图：少量，通常能检到 */\n    var nDrill = 2 + Math.floor(rng() * 2);\n    shouldTotal += nDrill;\n    for (var d = 0; d < nDrill; d++) {\n      var dx = Math.floor(5 + rng() * (scan.W - 10));\n      var dy = Math.floor(4 + rng() * (scan.H - 10));\n      var cD = clamp(0.7 + rng() * 0.2 - (confTh - 0.5) * 0.3, 0.2, 0.98);\n      if (cD >= confTh) { emit(dx, dy, 2, 6, '柱状', cD, true); tp++; }\n    }\n\n    /* 误检：confTh 低时多出假框 */\n    var nFP = Math.max(0, Math.round((0.55 - confTh) * 14));\n    for (var e = 0; e < nFP; e++) {\n      var ex = Math.floor(3 + rng() * (scan.W - 8));\n      var ey = Math.floor(3 + rng() * (scan.H - 8));\n      var cE = confTh + rng() * 0.12;\n      emit(ex, ey, 3, 3, '符号', cE, false); fp++;\n    }\n\n    var recall = shouldTotal ? tp / shouldTotal : 1;\n    var precision = (tp + fp) ? tp / (tp + fp) : 1;\n    return { dets: dets, recall: recall, precision: precision, tp: tp, fp: fp, total: shouldTotal };\n  }\n  M.detectObjects = detectObjects;\n\n  /* =========================================================\n     OCR 识别注记\n     ---------------------------------------------------------\n     每个注记真实文本已知，模拟 OCR 按字符错误率 err 出错。\n     返回 [{gt, pred, ok, conf}] + 整体准确率。\n     ========================================================= */\n  var OCR_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789J2K1T3P2O1C1D3S2';\n  function ocrRead(scan, err, seed) {\n    var rng = mulberry32((seed || 77) + Math.round(err * 100));\n    var out = [], correct = 0;\n    for (var n = 0; n < scan.notes.length; n++) {\n      var gt = scan.notes[n].text;\n      var pred = '';\n      for (var c = 0; c < gt.length; c++) {\n        if (rng() < err) {\n          var pick = OCR_ALPHABET[Math.floor(rng() * OCR_ALPHABET.length)];\n          pred += pick !== gt[c] ? pick : (pick === 'A' ? 'B' : 'A');\n        } else pred += gt[c];\n      }\n      var ok = pred === gt;\n      if (ok) correct++;\n      var conf = clamp(1 - err - rng() * 0.2, 0.3, 0.99);\n      out.push({ gt: gt, pred: pred, ok: ok, conf: conf });\n    }\n    return { results: out, acc: scan.notes.length ? correct / scan.notes.length : 1, correct: correct, total: scan.notes.length };\n  }\n  M.ocrRead = ocrRead;\n\n  /* =========================================================\n     版面分析 + 矢量追踪\n     ---------------------------------------------------------\n     版面分析：把扫描图分成 图区 / 图例区 / 注记区 三个区块。\n     矢量追踪：沿断层线像素重建折线矢量，gap 越大越能跨断裂连接。\n     返回 { regions, vectors, nVector, linkedGap }\n     ========================================================= */\n  function layoutAnalyze(scan) {\n    /* 简化：按像素类型分布划分区块（图区=断层区，图例区=符号区，注记区=注记区） */\n    var regs = [];\n    regs.push({ id: 'M', name: '图区', x: 2, y: 2, w: scan.W - 4, h: scan.H - 4, fill: '#eef1ee' });\n    var symMinX = 1e9, symMaxX = -1, symMinY = 1e9, symMaxY = -1;\n    for (var s = 0; s < scan.symbols.length; s++) {\n      var sy = scan.symbols[s];\n      if (sy.x < symMinX) symMinX = sy.x;\n      if (sy.x + sy.w > symMaxX) symMaxX = sy.x + sy.w;\n      if (sy.y < symMinY) symMinY = sy.y;\n      if (sy.y + sy.h > symMaxY) symMaxY = sy.y + sy.h;\n    }\n    if (symMaxX > symMinX) regs.push({ id: 'L', name: '图例区', x: symMinX - 1, y: symMinY - 1, w: symMaxX - symMinX + 2, h: symMaxY - symMinY + 2, fill: '#f7ece2' });\n    var noteMinX = 1e9, noteMaxX = -1, noteMinY = 1e9, noteMaxY = -1;\n    for (var n = 0; n < scan.notes.length; n++) {\n      var nt = scan.notes[n];\n      if (nt.x < noteMinX) noteMinX = nt.x;\n      if (nt.x + nt.w > noteMaxX) noteMaxX = nt.x + nt.w;\n      if (nt.y < noteMinY) noteMinY = nt.y;\n      if (nt.y + nt.h > noteMaxY) noteMaxY = nt.y + nt.h;\n    }\n    if (noteMaxX > noteMinX) regs.push({ id: 'N', name: '注记区', x: noteMinX - 1, y: noteMinY - 1, w: noteMaxX - noteMinX + 2, h: noteMaxY - noteMinY + 2, fill: '#e7eef9' });\n    return { regions: regs };\n  }\n  M.layoutAnalyze = layoutAnalyze;\n\n  function traceVectors(scan, linkGap) {\n    var vectors = [];\n    var linked = 0;\n    for (var f = 0; f < scan.faults.length; f++) {\n      var fl = scan.faults[f];\n      var pts = fl.pts.slice();\n      /* 模拟断裂：按 gap 连接相邻点，gap 越大越能跨断裂 */\n      var merged = [];\n      for (var i = 0; i < pts.length; i++) {\n        merged.push(pts[i]);\n        if (i < pts.length - 1) {\n          var d = Math.abs(pts[i + 1][0] - pts[i][0]) + Math.abs(pts[i + 1][1] - pts[i][1]);\n          if (d > 1 && d <= linkGap) { linked++; }\n        }\n      }\n      vectors.push({ id: fl.id, color: fl.color, pts: merged, name: fl.name, complete: true });\n    }\n    return { vectors: vectors, nVector: vectors.length, linked: linked };\n  }\n  M.traceVectors = traceVectors;\n\n  return M;\n});\n\n/* =========================================================\n   浏览器接线（Node require 时走 module.exports 分支返回，不执行）\n   ========================================================= */\nif (typeof window !== 'undefined' && !window.__g3ModelOnly) {\n  (function () {\n    'use strict';\n    var M = window.Model;\n    var doc = document;\n\n    function $(id) { return doc.getElementById(id); }\n    function num(v, n) { return Number(v).toFixed(n === undefined ? 2 : n); }\n    function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n\n    var SCALE = 8;   /* 栅格 64×48 → 512×384 */\n    var SCAN = M.genScanMap(20261105, 64, 48);\n\n    /* UI 状态 */\n    var detState = { confTh: 0.5 };\n    var ocrState = { err: 0.15 };\n    var vecState = { linkGap: 3 };\n\n    /* 屏 1 渲染：目标检测 */\n    function renderDet() {\n      var det = M.detectObjects(SCAN, detState.confTh, 20261105);\n      var s = '';\n      /* 断层线像素 */\n      for (var y = 0; y < 48; y++) for (var x = 0; x < 64; x++) {\n        var i = y * 64 + x;\n        if (SCAN.px[i] === 1) s += '<rect x=\"' + (x * SCALE) + '\" y=\"' + (y * SCALE) + '\" width=\"' + SCALE + '\" height=\"' + SCALE + '\" fill=\"#a97b55\" opacity=\"0.8\"/>';\n      }\n      /* 检测框：命中（实线绿），误检（虚线红） */\n      for (var d = 0; d < det.dets.length; d++) {\n        var b = det.dets[d];\n        var col = b.hit ? '#2f7d6b' : '#c0444a';\n        var dash = b.hit ? '' : ' stroke-dasharray=\"4 3\"';\n        s += '<rect x=\"' + (b.x * SCALE) + '\" y=\"' + (b.y * SCALE) + '\" width=\"' + (b.w * SCALE) + '\" height=\"' + (b.h * SCALE) + '\" fill=\"none\" stroke=\"' + col + '\" stroke-width=\"1.8\"' + dash + '/>';\n        s += '<text x=\"' + ((b.x + b.w + 1) * SCALE) + '\" y=\"' + (b.y * SCALE - 4) + '\" font-size=\"10\" fill=\"' + col + '\">' + b.cls + ' ' + num(b.conf, 2) + '<\/text>';\n      }\n      $('detChart').innerHTML = s;\n      $('roRecall').textContent = num(det.recall * 100, 0) + '%';\n      $('roPrecision').textContent = num(det.precision * 100, 0) + '%';\n      $('roDetTP').textContent = det.tp + ' / ' + det.total;\n      $('roDetFP').textContent = det.fp;\n      $('outConfTh').textContent = num(detState.confTh, 2);\n      $('detTip').textContent = '绿色实线 = 正确检出的对象框，红色虚线 = 误检框。阈值越高越保守（漏检多、误检少），越低越激进（漏检少、误检多）。';\n    }\n\n    /* 屏 2 渲染：OCR 识别 */\n    function renderOcr() {\n      var ocr = M.ocrRead(SCAN, ocrState.err, 20261105);\n      var s = '';\n      /* 注记区域块 */\n      for (var n = 0; n < ocr.results.length; n++) {\n        var r = ocr.results[n];\n        var note = SCAN.notes[n];\n        var col = r.ok ? '#2f7d6b' : '#c0444a';\n        s += '<rect x=\"' + (note.x * SCALE - 3) + '\" y=\"' + (note.y * SCALE - 6) + '\" width=\"' + (note.w * SCALE + 6) + '\" height=\"' + (SCALE + 12) + '\" rx=\"3\" fill=\"' + (r.ok ? '#e6f1ec' : '#f9efea') + '\" stroke=\"' + col + '\"/>';\n        s += '<text x=\"' + (note.x * SCALE + 2) + '\" y=\"' + (note.y * SCALE + 10) + '\" font-size=\"12\" fill=\"' + col + '\">' + r.pred + (r.ok ? ' ✓' : ' ✗') + '<\/text>';\n      }\n      $('ocrChart').innerHTML = s;\n      $('roOcrAcc').textContent = num(ocr.acc * 100, 0) + '%';\n      $('roOcrRight').textContent = ocr.correct + ' / ' + ocr.total;\n      $('outErr').textContent = num(ocrState.err, 2);\n      $('ocrTip').textContent = '绿色 = 识别正确，红色 = 识别错误。错误率越高，注记文本污染属性表的概率越大，需要人工校对。';\n    }\n\n    /* 屏 3 渲染：版面分析 + 矢量追踪 */\n    function renderVec() {\n      var lay = M.layoutAnalyze(SCAN);\n      var vec = M.traceVectors(SCAN, vecState.linkGap);\n      var s = '';\n      /* 版面区块 */\n      for (var r = 0; r < lay.regions.length; r++) {\n        var rg = lay.regions[r];\n        s += '<rect x=\"' + (rg.x * SCALE) + '\" y=\"' + (rg.y * SCALE) + '\" width=\"' + (rg.w * SCALE) + '\" height=\"' + (rg.h * SCALE) + '\" rx=\"6\" fill=\"' + rg.fill + '\" opacity=\"0.55\"/>';\n        s += '<text x=\"' + (rg.x * SCALE + 4) + '\" y=\"' + (rg.y * SCALE - 4) + '\" font-size=\"11\" fill=\"#79828a\" font-weight=\"600\">' + rg.name + '<\/text>';\n      }\n      /* 断层矢量追踪结果 */\n      for (var v = 0; v < vec.vectors.length; v++) {\n        var vt = vec.vectors[v];\n        var path = '';\n        for (var p = 0; p < vt.pts.length; p++) {\n          path += (p ? 'L' : 'M') + (vt.pts[p][0] * SCALE) + ' ' + (vt.pts[p][1] * SCALE);\n        }\n        s += '<path d=\"' + path + '\" fill=\"none\" stroke=\"' + vt.color + '\" stroke-width=\"2.4\" stroke-linecap=\"round\"/>';\n        s += '<text x=\"' + (vt.pts[0][0] * SCALE + 4) + '\" y=\"' + (vt.pts[0][1] * SCALE - 4) + '\" font-size=\"10\" fill=\"' + vt.color + '\" font-weight=\"600\">' + vt.name + '<\/text>';\n      }\n      $('vecChart').innerHTML = s;\n      $('roVectors').textContent = vec.nVector + ' 条';\n      $('roLinked').textContent = vec.linked;\n      $('outLinkGap').textContent = vecState.linkGap;\n      $('vecTip').textContent = '色块 = 版面分析识别的区块（图区/图例区/注记区），曲线 = 矢量追踪得到的断层线。gap 越大，越能跨断裂连接断开线条。';\n    }\n\n    /* 事件绑定 */\n    function bind() {\n      var inConf = $('pConfTh');\n      if (inConf) inConf.addEventListener('input', function () {\n        detState.confTh = parseFloat(inConf.value);\n        renderDet();\n      });\n      var inErr = $('pErr');\n      if (inErr) inErr.addEventListener('input', function () {\n        ocrState.err = parseFloat(inErr.value);\n        renderOcr();\n      });\n      var inGap = $('pLinkGap');\n      if (inGap) inGap.addEventListener('input', function () {\n        vecState.linkGap = parseInt(inGap.value, 10);\n        renderVec();\n      });\n    }\n\n    /* 抽屉上报 */\n    function setupDrawer() {\n      if (window.parent === window) return;\n      var secs = [];\n      [['sec1', '目标检测', 'detCtl'], ['sec2', 'OCR 识别', 'ocrCtl'], ['sec3', '版面分析+追踪', 'vecCtl']].forEach(function (s) {\n        var el = $(s[2]); if (!el) return;\n        el.querySelectorAll('input, button').forEach(function (c) {\n          if (c.type === 'range') c.setAttribute('value', c.value);\n        });\n        secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n      });\n      try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n      window.addEventListener('message', function (e) {\n        if (e.source !== window.parent) return;\n        var d = e.data;\n        if (!d || d.__drawer !== 'control') return;\n        var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n        if (!el) return;\n        if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      });\n    }\n\n    /* 启动 */\n    renderDet(); renderOcr(); renderVec(); bind(); setupDrawer();\n\n    /* 桥接对象：暴露模型层给 flow.js */\n    window.RemoteBridge = { M: M, live: function () { return { confTh: detState.confTh, err: ocrState.err, linkGap: vecState.linkGap }; } };\n  })();\n}\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   地质图件要素智能提取 · 算法解剖（检测 + OCR + 追踪）\n   ---------------------------------------------------------\n   把「扫描图件 → 矢量图层」拆成 6 步，每一步都跑真代码：\n\n     ① 扫描接入        统一分辨率、分块切图\n     ② 目标检测        定位图例符号 / 断层线 / 钻孔柱状图\n     ③ OCR 识别        把注记从像素读成文本\n     ④ 版面分析        理清图区 / 图例区 / 注记区\n     ⑤ 矢量追踪        沿断层线像素重建折线矢量\n     ⑥ 图例映射 + 抽检  符号 → 岩性语义，人工把关\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  function hexA(hex, a) {\n    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);\n    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';\n  }\n\n  /* 面板底部小结框 */\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* 扫描图栅格底图（断层线 / 符号 / 注记像素） */\n  function scanBase(scan, W, H, S, x0, y0) {\n    var s = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var i = y * W + x;\n        var col;\n        if (scan.px[i] === 1) col = '#c9a98a';\n        else if (scan.px[i] === 2) col = '#d9c39a';\n        else if (scan.px[i] === 3) col = '#b9c9dd';\n        else col = '#f1eee4';\n        s += G.rect(x0 + x * S, y0 + y * S, S, S, { fill: col, r: 0, op: 1 });\n      }\n    }\n    return s;\n  }\n\n  var W = 48, H = 36, S = 7;   /* 扫描区 48×36 → SVG 336×252 */\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.confTh, L.err, L.linkGap].join(',');\n    if (cache.key === key) return cache;\n    var scan = M.genScanMap(20261105, W, H);\n    var det = M.detectObjects(scan, L.confTh, 20261105);\n    var ocr = M.ocrRead(scan, L.err, 77);\n    var lay = M.layoutAnalyze(scan);\n    var vec = M.traceVectors(scan, L.linkGap);\n    cache = { key: key, L: L, scan: scan, det: det, ocr: ocr, lay: lay, vec: vec };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 扫描接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), scan = c.scan, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 扫描接入', '统一分辨率', C.blue);\n    s += G.panel(1, '② 分块切图', '并行检测', C.clay);\n    s += G.panel(2, '③ 标注准备', '图例符号每类 ≥200', C.jade);\n\n    var x0 = 30, y0 = 132;\n    s += scanBase(scan, W, H, S, x0, y0);\n    s += G.txt(x0, y0 - 12, '扫描地质图件 · ' + (W * S) + '×' + (H * S) + ' px · 300 dpi 归一', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '为什么先接入',\n      ['· 分辨率不足 300 dpi',\n       '  细线符号检测不到',\n       '· 单幅 5000×7000 太大',\n       '  必须分块才能并行',\n       '',\n       '图例符号每类 ≥ 200 个',\n       '实例，检测模型才有得学。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '第一步把扫描件整理成统一、可分块的输入——检测和 OCR 的地基', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '图件', v: '1.2 万幅' }, { k: '分辨率', v: '300 dpi' }, { k: '图例实例', v: '≥200/类' }], note: '扫描件先统一分辨率、分块切图，再备好图例标注——目标检测与 OCR 都是成熟技术，前提是把输入整理成它们吃得动的形态。' };\n  }\n\n  /* =========================================================\n     ② 目标检测\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), scan = c.scan, det = c.det, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 扫描图块', '输入', C.blue);\n    s += G.panel(1, '② 检测模型', 'Faster R-CNN / YOLO', C.jade);\n    s += G.panel(2, '③ 检测框', '位置 + 类别 + 置信度', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += scanBase(scan, W, H, S, x0, y0);\n    for (var d = 0; d < det.dets.length; d++) {\n      var b = det.dets[d];\n      var col = b.hit ? '#2f7d6b' : '#c0444a';\n      s += G.rect(x0 + b.x * S, y0 + b.y * S, Math.max(1, b.w * S), Math.max(1, b.h * S), {\n        fill: 'none', stroke: col, sw: 1.4, dash: b.hit ? '' : '4 3', r: 1\n      });\n      s += G.txt(x0 + (b.x + b.w) * S, y0 + b.y * S - 3, b.cls, { size: 7.6, fill: col, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '目标检测 · 检出 ' + det.tp + '/' + det.total + ' · 误检 ' + det.fp + ' · 阈值 ' + f(L.confTh, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '检测的现实',\n      ['· 断层线 → 折线框',\n       '· 图例符号 → 小方块框',\n       '· 钻孔柱状图 → 长条框',\n       '',\n       '符号小且密集是难点：',\n       '阈值高漏检多，低则误检多。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '目标检测把「图上有什么、在哪」答出来——符号、断层、柱状图都带框带类别', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '检出', v: det.tp + '/' + det.total }, { k: '误检', v: det.fp }, { k: '阈值', v: f(L.confTh, 2) }], note: '目标检测用成熟模型（Faster R-CNN / YOLO）定位图例符号、断层线、钻孔柱状图。难点在符号小且密集、图例体系不同——要分年代训练。' };\n  }\n\n  /* =========================================================\n     ③ OCR 识别\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), scan = c.scan, ocr = c.ocr, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 注记像素', '地名 / 代号 / 说明', C.blue);\n    s += G.panel(1, '② CRNN / OCR', '像素 → 字符序列', C.jade);\n    s += G.panel(2, '③ 注记文本', '可搜索 · 可入库', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += scanBase(scan, W, H, S, x0, y0);\n    for (var n = 0; n < ocr.results.length; n++) {\n      var r = ocr.results[n];\n      var note = scan.notes[n];\n      var col = r.ok ? '#2f7d6b' : '#c0444a';\n      s += G.rect(x0 + note.x * S - 2, y0 + note.y * S - 3, note.w * S + 4, S + 6, { r: 2, fill: hexA(col, 0.12), stroke: col, sw: 1 });\n      s += G.txt(x0 + note.x * S + 2, y0 + note.y * S + S * 0.7, r.pred + (r.ok ? '✓' : '✗'), { size: 7.6, fill: col, weight: 600 });\n    }\n    s += G.txt(x0, y0 - 12, 'OCR 识别 · 准确率 ' + f(ocr.acc * 100, 0) + '% · 错误率 ' + f(L.err, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, 'OCR 的现实',\n      ['· 注记 = 地名 + 地层代号',\n       '  + 符号说明',\n       '· CRNN / Transformer OCR',\n       '  像素 → 字符序列',\n       '',\n       '手写 / 模糊件易错：',\n       '错字会污染属性表。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, 'OCR 把图面注记从像素读成文本——地名、代号、说明都变成可检索字段', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '准确率', v: f(ocr.acc * 100, 0) + '%' }, { k: '正确', v: ocr.correct + '/' + ocr.total }, { k: '错误率', v: f(L.err, 2) }], note: 'OCR 用成熟模型把注记像素读成文本。难点在手写与模糊件易错——错误文本会污染属性表，需要人工校对或置信度过滤。' };\n  }\n\n  /* =========================================================\n     ④ 版面分析\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), scan = c.scan, lay = c.lay, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 扫描图', '整体布局', C.blue);\n    s += G.panel(1, '② 区块划分', '图区 / 图例 / 注记', C.jade);\n    s += G.panel(2, '③ 结构化', '每区各司其职', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += scanBase(scan, W, H, S, x0, y0);\n    for (var r = 0; r < lay.regions.length; r++) {\n      var rg = lay.regions[r];\n      var col = rg.id === 'M' ? '#7c9a8f' : rg.id === 'L' ? '#b26a39' : '#41699b';\n      s += G.rect(x0 + rg.x * S, y0 + rg.y * S, Math.max(1, rg.w * S), Math.max(1, rg.h * S), {\n        fill: hexA(col, 0.12), stroke: col, sw: 1.2, dash: '5 3', r: 4\n      });\n      s += G.txt(x0 + rg.x * S + 3, y0 + rg.y * S - 3, rg.name, { size: 8, fill: col, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '版面分析 · 识别 ' + lay.regions.length + ' 个区块', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '版面分析的用处',\n      ['· 图区：断层线 / 岩性',\n       '· 图例区：符号对照',\n       '· 注记区：文本说明',\n       '',\n       '分清了区块，后续检测、',\n       '追踪、映射才有的放矢。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '版面分析把一张图拆成「图区 / 图例区 / 注记区」——不同区用不同策略处理', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '区块', v: lay.regions.length }, { k: '图区', v: '断层+岩性' }, { k: '图例区', v: '符号对照' }], note: '版面分析理清图区、图例区、注记区的布局——图区做检测与追踪、图例区做符号对照、注记区做 OCR，各区块各司其职。' };\n  }\n\n  /* =========================================================\n     ⑤ 矢量追踪\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), scan = c.scan, vec = c.vec, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 断层像素', '低对比细线', C.blue);\n    s += G.panel(1, '② 沿像素追踪', '重建拓扑', C.jade);\n    s += G.panel(2, '③ 折线矢量', '跨断裂连接', C.clay);\n\n    var x0 = 30, y0 = 132;\n    s += scanBase(scan, W, H, S, x0, y0);\n    for (var v = 0; v < vec.vectors.length; v++) {\n      var vt = vec.vectors[v];\n      var path = '';\n      for (var p = 0; p < vt.pts.length; p++) {\n        path += (p ? 'L' : 'M') + (x0 + vt.pts[p][0] * S) + ' ' + (y0 + vt.pts[p][1] * S);\n      }\n      s += G.path(path, { fill: 'none', stroke: vt.color, sw: 2, cap: 'round' });\n      s += G.txt(x0 + vt.pts[0][0] * S + 3, y0 + vt.pts[0][1] * S - 4, vt.name, { size: 8, fill: vt.color, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '矢量追踪 · ' + vec.nVector + ' 条矢量 · 连接 ' + vec.linked + ' 处 · gap ' + L.linkGap, { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '追踪的现实',\n      ['· 断层是细长低对比线',\n       '  最易受扫描噪声干扰',\n       '· 线条断裂要跨缺口连接',\n       '  gap 越大越能连',\n       '',\n       '拓扑重建难：',\n       '断点连错就出错矢量。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '矢量追踪把断层线像素重建为带拓扑的折线——gap 越大越能跨断裂', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '矢量', v: vec.nVector + ' 条' }, { k: '连接处', v: vec.linked }, { k: 'gap', v: L.linkGap }], note: '矢量追踪沿断层线像素重建折线、补断裂。难点在线条断裂后的拓扑重建——断点连错会产生错误矢量，是矢量化质量的最大隐患。' };\n  }\n\n  /* =========================================================\n     ⑥ 图例映射 + 抽检\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), scan = c.scan, det = c.det, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 检测符号', '图例类别', C.blue);\n    s += G.panel(1, '② 图例对照表', '各年代体系', C.jade);\n    s += G.panel(2, '③ 岩性语义', '映射 + 抽检', C.clay);\n\n    var x0 = 30, y0 = 132;\n    /* 符号网格 + 映射结果 */\n    var gridX = 0, gridY = 0, cell = 26;\n    for (var si = 0; si < M.ROCK_SYM.length; si++) {\n      var rock = M.ROCK_SYM[si];\n      var gx = x0 + gridX * cell, gy = y0 + gridY * cell;\n      s += G.rect(gx, gy, cell - 4, cell - 4, { r: 4, fill: rock.fill, stroke: '#8a6b52', sw: 1 });\n      s += G.txt(gx + (cell - 4) / 2, gy + 16, rock.name, { size: 8.5, fill: '#4d565b', anchor: 'middle', weight: 600 });\n      gridX++;\n      if (gridX > 4) { gridX = 0; gridY++; }\n    }\n    s += G.txt(x0, y0 - 12, '图例映射 · 符号 → 岩性/构造语义 · 抽检 ' + Math.round(L.confTh * 100) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 132, 192, '映射的坑',\n      ['· 同一岩性在不同年代',\n       '  可能是不同符号',\n       '· 检测对了，映射错',\n       '  就叫「张冠李戴」',\n       '',\n       '没有图例对照表，',\n       '成果库会被污染。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '图例对照表把「哪个年代的符号」翻成「是什么岩性」——映射后抽检把关', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '岩性类', v: M.ROCK_SYM.length }, { k: '映射', v: '对照表' }, { k: '抽检', v: '≤10%' }], note: '最后用图例对照表把检测符号映射成岩性/构造语义，并抽检把关。图例体系跨年代不一致，没有对照表会张冠李戴——抽检修正回写训练集，图例表越用越全。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：地质图件要素智能提取<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 地质勘察 / 地质图件要素智能提取<\/span>\n  <h1>从「人工描图 1—2 人日」到「检测 + OCR + 追踪 · 小时级矢量化」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂目标检测、Q2 看懂 OCR 识别、Q3 版面分析 + 矢量追踪。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 扫描件矢量化全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「扫描件 → 黑盒 → 矢量图层」，而是<b>逐段展开<\/b>：扫描接入 → 目标检测 → OCR 识别 → 版面分析 → 矢量追踪 → 图例映射，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「扫描图件 → 矢量图层」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改检测阈值、OCR 错误率和连接 gap，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（检测框、识别文本、矢量要素）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>detectObjects / ocrRead / layoutAnalyze / traceVectors<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步用目标检测框说明「图上有什么、在哪」的定位逻辑；<b>②<\/b> 第 5 步把断层线追踪与断裂连接并排放，看得见「为什么线条断裂最易出错」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 目标检测 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">人工描图 1—2 人日/幅；目标检测自动定位符号与断层，压到小时级<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 2<\/span>\n    <h2>目标检测：扫描图上的符号、断层、柱状图在哪儿<\/h2>\n    <p class=\"leadline\">拖检测阈值，看对象框怎么随「保守 vs 激进」变化——阈值高漏检多、误检少，低则相反。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"detCtl\">\n    <div class=\"sl\">\n      <label>检测阈值<output id=\"outConfTh\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"pConfTh\" min=\"0.2\" max=\"0.9\" step=\"0.05\" value=\"0.5\">\n    <\/div>\n  <\/div>\n  <svg id=\"detChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"目标检测结果\"><\/svg>\n  <div class=\"rrow ro4\">\n    <div class=\"ro\"><span class=\"k\">召回率<\/span><b id=\"roRecall\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">精确率<\/span><b id=\"roPrecision\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">正确检出<\/span><b id=\"roDetTP\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">误检框<\/span><b id=\"roDetFP\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"detTip\">绿色实线 = 正确检出的对象框，红色虚线 = 误检框。阈值越高越保守（漏检多、误检少），越低越激进（漏检少、误检多）。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · OCR 识别 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>OCR<\/b>（CRNN / Transformer）把图面注记从像素读成文本<span class=\"qa-algo\">自然语言处理 · 文字识别<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3<\/span>\n    <h2>OCR 识别：地名、地层代号、符号说明变文本<\/h2>\n    <p class=\"leadline\">拖错误率模拟扫描件清晰度——手写、模糊件 OCR 易错，错误文本会污染属性表。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"ocrCtl\">\n    <div class=\"sl\">\n      <label>OCR 错误率<output id=\"outErr\">0.15<\/output><\/label>\n      <input type=\"range\" id=\"pErr\" min=\"0\" max=\"0.6\" step=\"0.05\" value=\"0.15\">\n    <\/div>\n  <\/div>\n  <svg id=\"ocrChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"OCR识别结果\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">识别准确率<\/span><b id=\"roOcrAcc\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">正确 / 总数<\/span><b id=\"roOcrRight\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"ocrTip\">绿色 = 识别正确，红色 = 识别错误。错误率越高，注记文本污染属性表的概率越大，需要人工校对或置信度过滤。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 版面分析 + 矢量追踪 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">版面分析理清区块 + 矢量追踪沿线条重建拓扑 → 可入库的矢量要素<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 4—5<\/span>\n    <h2>版面分析 + 矢量追踪：图怎么被拆成区、线怎么变成矢量<\/h2>\n    <p class=\"leadline\">色块 = 版面分析识别的区块，曲线 = 矢量追踪得到的断层线。拖 gap 看断线怎么跨缺口连接。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"vecCtl\">\n    <div class=\"sl\">\n      <label>连接 gap<output id=\"outLinkGap\">3<\/output><\/label>\n      <input type=\"range\" id=\"pLinkGap\" min=\"1\" max=\"6\" step=\"1\" value=\"3\">\n    <\/div>\n  <\/div>\n  <svg id=\"vecChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"版面分析与矢量追踪\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">矢量要素<\/span><b id=\"roVectors\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">断裂连接<\/span><b id=\"roLinked\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"vecTip\">色块 = 版面分析识别的区块（图区/图例区/注记区），曲线 = 矢量追踪得到的断层线。gap 越大，越能跨断裂连接断开线条。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>目标检测定位图例符号、断层线、钻孔柱状图。<\/div>\n    <div><b>实验 2 → STEP 3<\/b><br>OCR 把图面注记从像素读成文本。<\/div>\n    <div><b>实验 3 → STEP 4—5<\/b><br>版面分析理区块 + 矢量追踪成矢量要素。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：扫描图件由「纸面 + 断层线 + 图例符号 + 注记」合成，真值已知、仅供对比；目标检测、OCR 识别、版面分析与矢量追踪均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：一张扫描图件怎么一步步变成矢量图层',\n    stages: [\n      { name: '扫描接入', tag: '分辨率 + 分块', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '目标检测', tag: '定位符号/断层', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: 'OCR 识别', tag: '注记 → 文本', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '版面分析', tag: '图区/图例/注记', dur: 4400, draw: function (t, g) { return F.stage4(t); } },\n      { name: '矢量追踪', tag: '线条 → 矢量', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '图例映射', tag: '对照表 + 抽检', dur: 4600, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的扫描地质图件演示目标检测、OCR 识别与矢量追踪。","height":600};
  var META = {"id":"g3-map-extract","sceneId":"g3","title":"地质图件要素智能提取：扫描件到矢量图层的自动化"};
  var handle = null;
  var DEF = {"id":"g3-map-extract","sceneId":"g3","title":"地质图件要素智能提取：扫描件到矢量图层的自动化","methods":["cv","nlp"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"扫描图件","desc":"300 dpi 以上，单幅 5000×7000 像素"},{"label":"标注成本","value":"低","desc":"图例符号每类 ≥ 200 个实例即可"},{"label":"可见收益","value":"大幅提速","desc":"矢量化从 1—2 人日压到小时级"},{"label":"难度","value":"中","desc":"检测/OCR 成熟，难点在图例不统一与线条拓扑"}],"lede":"大量历史地质图以扫描件与 PDF 保存——图例、断层线、钻孔柱状图都只是像素，无法直接参与空间分析。要把它们复用进 GIS，得先矢量化：把图上的线条、符号、注记都变成可查询、可编辑、带语义的矢量要素。智能方法把「人工描图」升级为「目标检测 + OCR + 版面分析 + 矢量追踪」，一幅图件从 1—2 人日压到小时级。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>历史地质图是<b>像素<\/b>不是要素：图上画着地层界线、断层、岩性符号和注记，但都是图像，GIS 无法直接查询或叠加分析。要复用，必须先<b>人工矢量化<\/b>——沿线条描出矢量、给每个符号标上语义、把注记敲成文本。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>人工描图慢<\/b>——一幅 5000×7000 像素的图件矢量化要 1—2 人日，历史图件数以万计<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>外包质量参差<\/b>——不同人描的线对不齐、符号漏标，返工成本高<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>图例体系不统一<\/b>——不同年代同一符号可能代表不同岩性，直接套模板会张冠李戴<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工矢量化的痛点\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">人工矢量化：慢 · 质量参差 · 图例不统一<\/text><rect x=\"20\" y=\"36\" width=\"286\" height=\"180\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"163\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">人工描图<\/text><path d=\"M40 170 L150 120 L260 165\" stroke=\"#b26a39\" stroke-width=\"2\" fill=\"none\"/><path d=\"M40 180 L150 132 L260 178\" stroke=\"#8aa77f\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/><circle cx=\"150\" cy=\"120\" r=\"6\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"1.5\"/><text x=\"80\" y=\"90\" font-size=\"8.5\" fill=\"#8a4f27\">沿线条描矢量<\/text><text x=\"150\" y=\"205\" font-size=\"8.5\" fill=\"#8a6b52\">一幅 1—2 人日 · 数以万计<\/text><text x=\"150\" y=\"220\" font-size=\"8.5\" fill=\"#8a6b52\">不同人描的质量参差<\/text><rect x=\"318\" y=\"36\" width=\"282\" height=\"180\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"459\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">图例体系不统一<\/text><text x=\"340\" y=\"82\" font-size=\"8.5\" fill=\"#4d565b\">1960s 图<\/text><rect x=\"400\" y=\"70\" width=\"26\" height=\"26\" fill=\"#cbbf9a\" stroke=\"#8a6b52\"/><text x=\"413\" y=\"87\" text-anchor=\"middle\" font-size=\"8\" fill=\"#4d565b\">↗<\/text><text x=\"436\" y=\"84\" font-size=\"8\" fill=\"#8a4f27\">砂岩<\/text><text x=\"340\" y=\"128\" font-size=\"8.5\" fill=\"#4d565b\">1990s 图<\/text><rect x=\"400\" y=\"116\" width=\"26\" height=\"26\" fill=\"#e0c88a\" stroke=\"#8a6b52\"/><text x=\"413\" y=\"133\" text-anchor=\"middle\" font-size=\"8\" fill=\"#4d565b\">◆<\/text><text x=\"436\" y=\"130\" font-size=\"8\" fill=\"#2f7d6b\">砂岩<\/text><text x=\"340\" y=\"174\" font-size=\"8.5\" fill=\"#4d565b\">同一「砂岩」两种符号<\/text><text x=\"340\" y=\"190\" font-size=\"8.5\" fill=\"#8a4f27\">直接套模板会张冠李戴<\/text><text x=\"340\" y=\"208\" font-size=\"8.5\" fill=\"#8a6b52\">图例体系不一致 → 需对照表<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「人工描图」换成 <b>「检测 + 识别 + 追踪」<\/b>流水线：目标检测定位图例符号与断层线，OCR 读图面注记，版面分析理清区块结构，再按图例映射规则把线条追踪成矢量要素。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>目标检测<\/b>——定位图例符号、断层线、钻孔柱状图等对象，给出它们在图上的位置框<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>OCR 识别注记<\/b>——把地名、地层代号、符号说明从像素读成文本<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>版面分析 + 矢量追踪<\/b>——理清图区/图例区/注记区布局，沿线条追踪成可入库的矢量要素<\/span><\/div><\/div><p>落地形态：矢量化从「逐幅人工描图」变成「批量自动 + 人工抽检」，外包质量问题被算法一致性取代。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"扫描图件矢量化流水线\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">扫描件 → 目标检测 + OCR + 版面分析 → 矢量图层<\/text><rect x=\"20\" y=\"40\" width=\"140\" height=\"150\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">扫描地质图件<\/text><rect x=\"32\" y=\"74\" width=\"116\" height=\"88\" fill=\"#efece2\"/><path d=\"M42 130 L90 100 L140 128\" stroke=\"#9ba3a9\" stroke-width=\"1.5\" fill=\"none\"/><circle cx=\"90\" cy=\"100\" r=\"4\" fill=\"none\" stroke=\"#9ba3a9\"/><text x=\"90\" y=\"155\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">5000×7000 px<\/text><path d=\"M164 115 L190 115\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"194\" y=\"40\" width=\"150\" height=\"150\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"269\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">目标检测 + OCR<\/text><text x=\"269\" y=\"86\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">检测符号 / 断层 / 柱状图<\/text><text x=\"269\" y=\"102\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">OCR 读注记文本<\/text><text x=\"269\" y=\"128\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每个对象一个位置框<\/text><text x=\"269\" y=\"144\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每段注记一串文字<\/text><path d=\"M348 115 L374 115\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"378\" y=\"40\" width=\"150\" height=\"150\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"453\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">版面分析 + 追踪<\/text><text x=\"453\" y=\"86\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">理清图区 / 图例 / 注记区<\/text><text x=\"453\" y=\"102\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">沿线条追踪成矢量<\/text><text x=\"453\" y=\"128\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按图例映射规则<\/text><text x=\"453\" y=\"144\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">线条 → 矢量要素<\/text><rect x=\"20\" y=\"204\" width=\"580\" height=\"36\" rx=\"6\" fill=\"#e7eef9\"/><text x=\"310\" y=\"226\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">批量自动 + 人工抽检 → 一幅从 1—2 人日压到小时级<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>扫描地质图件<\/b>：300 dpi 以上，单幅 5000×7000 像素，图例符号每类 ≥ 200 个实例（检测模型的训练数据）；<b>图例—语义对照表<\/b>：覆盖各年代图例体系，人工整理、一次性投入；<b>图面注记文本<\/b>：地名、地层代号、符号说明的文字转录校对 ≥ 2000 行（OCR 训练与校验）。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">三类数据 + 关键现实<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">扫描地质图件<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">300 dpi · 单幅 5000×7000<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">图例符号每类 ≥ 200 实例<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">图例—语义对照表<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">覆盖各年代图例体系<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">人工整理，一次性投入<\/text><rect x=\"20\" y=\"106\" width=\"582\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">图面注记文本<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">地名 · 地层代号 · 符号说明<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">文字转录校对 ≥ 2000 行<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"310\" y=\"202\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">关键现实：图例体系跨年代不一致 → 没有对照表，检测对了也可能映射错<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>图例体系不统一<\/b>——同一岩性在不同年代图上是不同符号，检测模型和映射规则要分开训练<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>线条断裂<\/b>——扫描噪点、折痕让线条断裂，拓扑重建难，追踪会中途断开<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>OCR 准确率<\/b>——手写注记、模糊扫描件 OCR 易错，错误文本会污染属性表<\/span><\/div><\/div><p>改进路线按成本从低到高：先做 <b>目标检测 + OCR<\/b>（复用成熟模型 + 图例标注）出基线；再加 <b>版面分析<\/b>理清区块、<b>矢量追踪<\/b>重建拓扑；最后用 <b>图例对照表<\/b>做语义映射 + 人工抽检把关。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 图例体系不统一<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">同岩性不同符号<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">目标检测 + OCR 基线<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">复用成熟模型 + 图例标注<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 线条断裂<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">扫描噪点 / 折痕<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">版面分析 + 矢量追踪<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">理区块 · 重建拓扑<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ OCR 准确率<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">手写注记 / 模糊件<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">图例对照表 + 人工抽检<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">语义映射 · 抽检把关<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">检测+OCR 基线 → 版面分析+追踪 → 图例对照+人工抽检<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个图件库的扫描件矢量化改造","lead":["某地质资料馆有 1.2 万幅历史扫描图件，此前靠外包人工描图矢量化，每幅 1—2 人日、质量参差、返工多。目标：用目标检测 + OCR + 版面分析 + 矢量追踪的流水线，把矢量化压到小时级，图例映射正确率显著提升。","注意第 2、3、4 步：目标检测、OCR 识别、版面分析 + 矢量追踪是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["历史图件","1.2 万幅"],["单幅像素","5000×7000"],["人工描图","1—2 人日"],["自动矢量化","小时级"],["图例映射","≥95%"],["抽检率","≤10%"]],"steps":[{"name":"扫描图件接入","role":"数据","do":"把扫描地质图件按图幅整理入库，统一分辨率（300 dpi 以上）、分块切图以便并行检测。示范页屏 1 展示扫描图件如何被切块、标注。","effect":"一套统一格式、可分块的扫描图件，供检测模型并行处理。","trap":"分辨率不足 300 dpi，细线符号与注记检测不到。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">扫描接入：统一分辨率 → 分块切图<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">扫描图件<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">5000×7000 px<\/text><path d=\"M178 68 L202 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">统一 300 dpi<\/text><text x=\"281\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">分辨率归一<\/text><path d=\"M360 68 L384 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">分块切图<\/text><text x=\"488\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">并行检测<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：分辨率不足 300 dpi → 细线符号、注记检测不到<\/text><\/svg>"},{"name":"目标检测定位对象","role":"算法核心","do":"用目标检测（Faster R-CNN / YOLO）定位图上的图例符号、断层线、钻孔柱状图等对象，给每个对象一个位置框与类别。示范页屏 1 实时检测合成扫描图上的符号。","effect":"图上的符号、断层、柱状图都被定位成带框带类别的对象。","trap":"图例符号小且密集，小目标易漏检；图例体系不同，需分年代训练。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">目标检测：扫描图 → 位置框 + 类别<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">扫描图块<\/text><path d=\"M60 76 L140 120 M200 100 L90 60\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" fill=\"none\"/><circle cx=\"150\" cy=\"60\" r=\"6\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.5\"/><path d=\"M188 90 L204 90\" stroke=\"#9ba3a9\" stroke-width=\"1.4\"/><path d=\"M188 120 L356 120\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"196\" y=\"42\" width=\"190\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">检测框 + 类别<\/text><rect x=\"206\" y=\"52\" width=\"44\" height=\"26\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><text x=\"228\" y=\"70\" text-anchor=\"middle\" font-size=\"8\" fill=\"#22604f\">断层<\/text><rect x=\"256\" y=\"74\" width=\"44\" height=\"26\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><text x=\"278\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#22604f\">符号<\/text><rect x=\"320\" y=\"52\" width=\"44\" height=\"26\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><text x=\"342\" y=\"70\" text-anchor=\"middle\" font-size=\"8\" fill=\"#22604f\">柱状<\/text><path d=\"M394 77 L414 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"418\" y=\"42\" width=\"178\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"507\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">带框带类别的对象<\/text><text x=\"507\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">送入下一步<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：图例符号小且密集 → 小目标漏检；图例体系不同 → 分年代训练<\/text><\/svg>"},{"name":"OCR 识别注记","role":"算法核心","do":"用 OCR（CRNN / Transformer OCR）把图面注记——地名、地层代号、符号说明——从像素读成文本。示范页屏 2 实时识别合成图上的注记文本。","effect":"图面注记变成可搜索、可入库的文本字段。","trap":"手写注记、模糊扫描件 OCR 易错，错误文本会污染属性表。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">OCR：注记像素 → 文本<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">注记像素<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">地名 / 代号 / 说明<\/text><path d=\"M188 77 L212 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"216\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"291\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">CRNN / OCR<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">像素 → 字符序列<\/text><path d=\"M370 77 L394 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"398\" y=\"42\" width=\"198\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"497\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">注记文本<\/text><text x=\"497\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">可搜索 · 可入库<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：手写 / 模糊 → OCR 易错 → 错误文本污染属性表<\/text><\/svg>"},{"name":"版面分析与矢量追踪","role":"工程环节","do":"版面分析把图区/图例区/注记区理清，矢量追踪沿检测到的线条像素重建拓扑、生成可入库的矢量要素。示范页屏 3 展示版面结构识别与线条追踪。","effect":"图上线条变成带拓扑的矢量要素，图例区与注记区被正确分离。","trap":"线条断裂后拓扑重建难，追踪中途断开，需连接与延伸策略。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">版面分析 + 追踪：区块理清 → 线条成矢量<\/text><rect x=\"24\" y=\"42\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"109\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">版面分析<\/text><text x=\"109\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">图区 / 图例 / 注记区<\/text><path d=\"M198 77 L222 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"226\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"301\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">矢量追踪<\/text><text x=\"301\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">沿线条重建拓扑<\/text><path d=\"M380 77 L404 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"188\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"502\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">矢量要素<\/text><text x=\"502\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">带拓扑 · 可入库<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：线条断裂 → 拓扑重建难 → 追踪中途断开<\/text><\/svg>"},{"name":"图例映射与语义入库","role":"算法核心","do":"用图例—语义对照表，把检测到的符号类别映射成岩性/构造语义，注记文本与矢量要素关联，生成带属性的矢量图层。示范页屏 3 展示图例映射结果。","effect":"符号从「哪个年代画的」变成「是什么岩性」，矢量要素带完整语义属性。","trap":"无对照表时检测对了也映射错，张冠李戴污染成果库。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">图例映射：符号 → 岩性/构造语义<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">检测符号类别<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">来自检测<\/text><path d=\"M178 68 L202 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">图例对照表<\/text><text x=\"281\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">各年代体系<\/text><path d=\"M360 68 L384 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">语义属性<\/text><text x=\"488\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">岩性 / 构造<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：无对照表 → 检测对了也映射错 → 张冠李戴<\/text><\/svg>"},{"name":"质检与抽检入库","role":"人工确认","do":"自动矢量化结果按图幅抽检（≤10%），错误修正回写训练集；更新图例对照表覆盖新年代体系。示范页屏 3 展示抽检与回写。","effect":"抽检把关质量，修正样本回流训练，图例对照表越用越全。","trap":"只自动不抽检，系统性错误（如图例映射错）会污染整个成果库。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">质检回写：自动结果 → 抽检 → 修正回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">自动矢量化<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">批量结果<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">抽检 ≤10%<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">人工把关<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">修正回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">训练集 + 图例表<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只自动不抽检 → 系统性错误污染成果库<\/text><\/svg>"}],"metrics":{"title":"怎么算「矢量化矢对了」","html":"<p>核心看 <b>图例映射正确率<\/b>：检测符号被映射成语义正确的岩性/构造的比例（越高越好），以及 <b>矢量要素完整率<\/b>（检测到并成功追踪的要素占比）。<\/p><p>检测本身验收用 <b>目标检测 mAP<\/b>、<b>OCR 准确率<\/b>；但必须<b>按年代分块评估<\/b>——不同图例体系分开验证，否则旧图新图混在一起精度虚高。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='矢量化效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>某图件库 1.2 万幅 · 人工外包 vs 智能流水线<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>图例映射正确率<\/text><rect x='60' y='82' width='70' height='52' fill='#d9b78e'/><text x='95' y='114' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>82%<\/text><text x='95' y='130' text-anchor='middle' font-size='8' fill='#8a6b52'>人工外包<\/text><rect x='180' y='58' width='70' height='76' fill='#2f7d6b'/><text x='215' y='94' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>95%<\/text><text x='215' y='110' text-anchor='middle' font-size='8' fill='#b9d8cb'>智能流水线<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>映射更准且口径一致<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>单幅矢量化耗时<\/text><rect x='400' y='56' width='90' height='78' fill='#d9b78e'/><text x='445' y='92' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>1—2 人日<\/text><text x='445' y='108' text-anchor='middle' font-size='8' fill='#8a6b52'>人工外包<\/text><rect x='540' y='98' width='70' height='36' fill='#2f7d6b'/><text x='575' y='120' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>小时级<\/text><text x='575' y='136' text-anchor='middle' font-size='8' fill='#b9d8cb'>智能流水线<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>耗时降一个量级<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 图例映射正确率 × 矢量要素完整率 × 按年代分块评估 · 三项都要达标<\/text><\/svg><\/p>"},"fails":[{"name":"图例张冠李戴","why":"图例体系跨年代不一致，无对照表时检测对了符号却映射错岩性，成果库被污染。"},{"name":"线条追踪断开","why":"扫描噪点、折痕让线条断裂，拓扑重建难，矢量要素中途断开、不完整。"},{"name":"OCR 文本污染","why":"手写注记、模糊扫描件 OCR 易错，错误文本写入属性表，影响后续检索。"},{"name":"小目标漏检","why":"图例符号小且密集，检测模型对小目标漏检，矢量化结果缺要素。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的扫描地质图件演示目标检测、OCR 识别与矢量追踪。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
